<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref,toRef,watch,reactive} from 'vue'
import {X} from 'lucide-vue-next'
import {api,post} from '../../../api'
import {useDocumentFieldPagination} from './documentFieldPagination'

type CandidateField={id:string;scope:string;row_key:string;field_key:string;normalized_value:unknown;raw_value:unknown;confirmed_value?:unknown;confidence?:string|number;page_number:number;source:{filename:string}}
type Group={id:string;intake_id:string;group_key:string;status:string;row_version:number;project_id?:string|null;relationship?:any;fields:CandidateField[];mold_mappings?:any[]}
const props=defineProps<{group:Group;refreshError?:string;archived?:boolean}>()
const emit=defineEmits<{close:[];reviewed:[];error:[message:string]}>()
const {page,total,pageCount,start,end,visibleFields,goTo}=useDocumentFieldPagination(toRef(props,'group'))
const pageNumbers=computed(()=>Array.from({length:pageCount.value},(_,index)=>index+1))
const panel=ref<HTMLElement|null>(null),content=ref<HTMLElement|null>(null),closeButton=ref<HTMLButtonElement|null>(null)
const candidates=ref<any>({projects:[],resolution:''}),loading=ref(false),saving=ref(false),intent=ref<any>(null),intentBusy=ref(false)
const values=reactive<Record<string,string>>({}),moldMappings=reactive<Record<string,string>>({})
const projectId=ref(''),relationshipType=ref<'NEW'|'DUPLICATE'|'REVISION'|'SUPPLEMENT'|'REPLACEMENT'>('NEW'),relationshipTarget=ref(''),relationshipReason=ref('首次合同')
const fieldNames:Record<string,string>={contract_number:'合同编号',customer_name:'客户名称',signed_date:'签订日期',amount:'金额',currency:'币种',project_number:'项目编号',external_order_number:'外部订单号',due_date:'交期',customer_mold_number:'客户模号',machine_model:'产品型号',material_number:'物料编号',name:'付款节点',ratio:'比例',condition:'付款条件',term_days:'账期天数'}
const scopeNames:Record<string,string>={HEADER:'合同信息',MOLD:'模具明细',PAYMENT:'付款节点'}
const relationshipNames:Record<string,string>={NEW:'新合同',DUPLICATE:'重复合同',REVISION:'修订合同',SUPPLEMENT:'补充合同',REPLACEMENT:'替代合同'}
const editable=computed(()=>props.group.status==='AWAITING_FIELD_CONFIRMATION'&&!props.archived)
const selectedProject=computed(()=>candidates.value.projects?.find((row:any)=>row.id===projectId.value))
const moldRows=computed(()=>Array.from(new Set(props.group.fields.filter(field=>field.scope==='MOLD').map(field=>String(field.row_key)))))
function scalar(v:unknown){const raw=v&&typeof v==='object'&&'value' in (v as any)?(v as any).value:v;return raw==null?'':typeof raw==='object'?JSON.stringify(raw):String(raw)}
function display(v:unknown){const text=scalar(v);return text===''?'未识别':text}
function fieldLabel(field:CandidateField){return `${scopeNames[field.scope]||field.scope} · ${field.row_key} · ${fieldNames[field.field_key]||field.field_key}`}
function seed(){for(const field of props.group.fields)values[field.id]=scalar(field.confirmed_value??field.normalized_value??field.raw_value);projectId.value=props.group.project_id||candidates.value.projects?.[0]?.id||'';for(const row of props.group.mold_mappings||[])moldMappings[row.row_key]=row.mold_id;relationshipType.value=props.group.relationship?.relation_type||'NEW';relationshipTarget.value=props.group.relationship?.target_contract_id||'';relationshipReason.value=props.group.relationship?.reason||'首次合同'}
async function loadCandidates(){loading.value=true;try{candidates.value=await api(`/contract-intakes/${encodeURIComponent(props.group.id)}/candidates`);seed()}catch(error:any){emit('error',error.message);seed()}finally{loading.value=false}}
watch(()=>props.group.id,()=>{goTo(1);void loadCandidates()},{immediate:true})
watch(()=>props.group.fields,seed,{deep:true})
function changePage(event:Event){goTo(Number((event.target as HTMLSelectElement).value))}
function requestPayload(){const project=selectedProject.value;if(!project)throw new Error('请选择并确认目标项目');const missing=moldRows.value.filter(row=>!moldMappings[row]);if(missing.length)throw new Error(`还有 ${missing.length} 条模具明细未关联正式模具`);if(props.group.fields.some(field=>values[field.id]===undefined))throw new Error('请确认全部合同字段');return {contract_intake_group_id:props.group.id,expected_version:props.group.row_version,project_id:project.id,project_version:project.row_version,confirmed_fields:props.group.fields.map(field=>({field_id:field.id,confirmed_value:{value:values[field.id]??''}})),mold_mappings:moldRows.value.map(row_key=>({row_key,mold_id:moldMappings[row_key]})),relationship:{relation_type:relationshipType.value,target_contract_id:relationshipTarget.value||null,reason:relationshipReason.value.trim()||'人工复核'}}}
async function prepareReview(){if(!editable.value||saving.value)return;saving.value=true;try{intent.value=await post(`/contract-intake-groups/${encodeURIComponent(props.group.id)}/review-intent`,requestPayload())}catch(error:any){emit('error',error.message)}finally{saving.value=false}}
async function confirmReview(){if(!intent.value||intentBusy.value)return;intentBusy.value=true;try{await post(`/human-actions/${intent.value.id}/confirm`,{challenge:intent.value.challenge});intent.value=null;emit('reviewed');emit('close')}catch(error:any){if([403,409].includes(error.status))intent.value=null;emit('error',error.message)}finally{intentBusy.value=false}}
function valueChanged(field:CandidateField,event:Event){values[field.id]=(event.target as HTMLInputElement).value}
watch(page,()=>{if(content.value)content.value.scrollTop=0},{flush:'post'})
let previousFocus:HTMLElement|null=null,previousOverflow=''
function keydown(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();if(intent.value)intent.value=null;else emit('close');return}if(event.key!=='Tab'||!panel.value)return;const focusable=Array.from(panel.value.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),summary,[tabindex="0"]')).filter(el=>el.getClientRects().length>0);const first=focusable[0],last=focusable[focusable.length-1],active=document.activeElement;if(!first){event.preventDefault();panel.value.focus({preventScroll:true});return}if(!focusable.includes(active as HTMLElement)||(event.shiftKey&&active===first)||(!event.shiftKey&&active===last)){event.preventDefault();(event.shiftKey?last:first).focus({preventScroll:true})}}
onMounted(()=>{previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';window.addEventListener('keydown',keydown,true);closeButton.value?.focus({preventScroll:true})})
onBeforeUnmount(()=>{window.removeEventListener('keydown',keydown,true);document.body.style.overflow=previousOverflow;if(previousFocus?.isConnected&&(panel.value?.contains(document.activeElement)||document.activeElement===document.body))previousFocus.focus({preventScroll:true})})
</script>

<template>
 <Teleport to="body"><div class="modal-shade document-fields-shade" @click.self="emit('close')"><section ref="panel" class="modal document-fields-dialog" role="dialog" aria-modal="true" :aria-label="`${group.group_key} · 候选字段`" tabindex="-1">
  <header class="fields-header"><div><h2>{{group.group_key}} · 候选字段</h2><p class="muted">共 {{total}} 个字段 · 第 {{group.row_version}} 版 · {{editable?'可编辑复核':'只读查看'}}</p></div><button ref="closeButton" type="button" class="icon-button fields-close" aria-label="关闭候选字段" @click="emit('close')"><X :size="20"/></button></header>
  <div class="fields-notice"><p>{{editable?'请逐项核对候选值、项目、模具和合同关系，点击“准备复核”后再确认执行。':'字段已完成复核或当前会话只读，请查看复核结果。'}}</p><p v-if="refreshError" class="fields-error" role="alert">{{refreshError}}。显示内容可能不是最新状态。</p></div>
  <div ref="content" class="fields-content" tabindex="0" aria-label="当前页候选字段">
   <section v-if="editable||group.status==='READY_FOR_DRAFT'" class="review-context"><label>目标项目<select v-model="projectId" :disabled="!editable||loading"><option value="">请选择项目</option><option v-for="project in candidates.projects||[]" :key="project.id" :value="project.id">{{project.code}} · {{project.name}} · 匹配 {{project.score}}</option></select></label><p v-if="!loading&&!candidates.projects?.length" class="fields-error">当前账号没有可见的项目候选，不能完成复核。</p><label>合同关系<select v-model="relationshipType" :disabled="!editable"><option v-for="(name,key) in relationshipNames" :key="key" :value="key">{{name}}</option></select></label><label v-if="relationshipType!=='NEW'">目标合同 ID<input v-model="relationshipTarget" :disabled="!editable"/></label><label>复核原因<input v-model="relationshipReason" :disabled="!editable"/></label></section>
   <table v-if="total"><colgroup><col class="scope-col"/><col class="name-col"/><col class="value-col"/><col class="source-col"/></colgroup><thead><tr><th>类别／行</th><th>字段</th><th>{{editable?'确认值':'候选值'}}</th><th>来源</th></tr></thead><tbody><tr v-for="field in visibleFields" :key="field.id"><td>{{scopeNames[field.scope]||field.scope}} · {{field.row_key}}</td><td>{{fieldNames[field.field_key]||field.field_key}}</td><td><input v-if="editable" :value="values[field.id]" :aria-label="fieldLabel(field)" @input="valueChanged(field,$event)"/><span v-else>{{display(field.confirmed_value??field.normalized_value)}}</span><small v-if="field.confidence!=null" class="confidence">置信度 {{field.confidence}}</small></td><td><span>{{field.source.filename}} · 第 {{field.page_number}} 页</span><details><summary>原文依据</summary><p>{{display(field.raw_value)}}</p></details></td></tr></tbody></table>
   <section v-if="editable&&moldRows.length" class="mold-mappings"><h3>模具明细与正式模具</h3><label v-for="rowKey in moldRows" :key="rowKey">{{rowKey}}<select v-model="moldMappings[rowKey]"><option value="">请选择正式模具</option><option v-for="mold in selectedProject?.molds||[]" :key="mold.id" :value="mold.id">{{mold.internal_number}} · {{mold.name}}</option></select></label></section><p v-else-if="!total" class="fields-empty">当前合同分组暂无可查看的候选字段。</p>
  </div>
  <footer class="fields-footer"><span role="status" aria-live="polite">共 {{total}} 个字段 · 当前 {{start}}–{{end}} 个</span><nav class="fields-pagination" aria-label="候选字段分页"><button type="button" :disabled="page<=1" @click="goTo(page-1)">上一页</button><label>第 <select :value="page" :disabled="pageCount<=1" aria-label="跳转候选字段页码" @change="changePage"><option v-for="number in pageNumbers" :key="number" :value="number">{{number}}</option></select> / {{pageCount}} 页</label><button type="button" :disabled="page>=pageCount" @click="goTo(page+1)">下一页</button></nav><button v-if="editable" type="button" class="primary" :disabled="saving||loading" @click="prepareReview">{{saving?'正在准备…':'准备复核'}}</button></footer>
  <div v-if="intent" class="intent-shade"><section class="intent-card" role="dialog" aria-modal="true" aria-label="确认合同字段复核"><h3>请确认合同字段复核</h3><dl><template v-for="(value,key) in intent.display||{}" :key="String(key)"><dt>{{key}}</dt><dd>{{display(value)}}</dd></template></dl><p>确认后会记录人工字段、项目、模具和合同关系复核结果，状态变为“可准备审批”；不会直接创建合同。</p><div class="intent-actions"><button type="button" :disabled="intentBusy" @click="intent=null">返回修改</button><button type="button" class="primary" :disabled="intentBusy" @click="confirmReview">{{intentBusy?'正在确认…':'确认执行'}}</button></div></section></div>
 </section></div></Teleport>
</template>

<style scoped>
.document-fields-shade{padding:24px;overscroll-behavior:contain}.document-fields-dialog{position:relative;display:flex;flex-direction:column;width:min(1180px,calc(100vw - 48px));height:min(820px,calc(100dvh - 48px));max-height:calc(100dvh - 48px);padding:0;overflow:hidden;color:var(--text);background:var(--surface)}.fields-header{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-shrink:0;padding:18px 22px;border-bottom:1px solid var(--border)}h2{margin:0;font-size:18px;overflow-wrap:anywhere}.muted{margin:6px 0 0;color:var(--muted);font-size:12px}.fields-close{flex-shrink:0;width:32px;height:32px}.fields-notice{flex-shrink:0;padding:10px 22px;border-bottom:1px solid var(--border);color:var(--muted)}.fields-notice p{margin:0;font-size:12px;line-height:1.6}.fields-notice .fields-error{margin-top:6px;color:var(--error,#b4534b)}.fields-content{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain}.review-context{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px;padding:14px 22px;border-bottom:1px solid var(--border)}.review-context label,.mold-mappings label{display:grid;gap:5px;color:var(--muted);font-size:12px}.review-context input,.review-context select,.mold-mappings select,td input{width:100%;min-height:34px;padding:6px 8px;border:1px solid var(--border);border-radius:6px;background:var(--surface);color:var(--text)}.mold-mappings{display:grid;gap:10px;padding:14px 22px;border-top:1px solid var(--border)}.mold-mappings h3{margin:0;font-size:14px}.mold-mappings label{grid-template-columns:90px 1fr;align-items:center}.confidence{display:block;margin-top:4px;color:var(--muted)}table{width:100%;min-width:720px;table-layout:fixed;border-collapse:separate;border-spacing:0;font-size:12px}.scope-col{width:16%}.name-col{width:14%}.value-col{width:34%}.source-col{width:36%}th,td{text-align:left;padding:10px 12px;border:0;border-bottom:1px solid var(--border);vertical-align:top;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}th{position:sticky;top:0;z-index:1;background:var(--surface);color:var(--muted);font-weight:600}td input{box-sizing:border-box}summary{cursor:pointer;margin-top:6px;color:var(--accent)}details p{margin:6px 0 0;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}.fields-empty{padding:48px 20px;text-align:center;color:var(--muted)}.fields-footer{display:flex;align-items:center;justify-content:flex-end;flex-wrap:wrap;gap:12px;flex-shrink:0;padding:14px 22px;border-top:1px solid var(--border);font-size:12px;color:var(--muted)}.fields-footer>span{margin-right:auto}.fields-pagination{display:flex;align-items:center;gap:10px}.fields-pagination label{display:flex;flex-direction:row;align-items:center;gap:6px;white-space:nowrap;color:var(--muted)}.fields-pagination select{width:66px;padding:6px}.fields-pagination button{padding:7px 12px;font-size:12px}.intent-shade{position:absolute;inset:0;z-index:5;display:grid;place-items:center;padding:24px;background:rgba(15,23,42,.38)}.intent-card{width:min(680px,100%);max-height:90%;overflow:auto;padding:22px;border-radius:12px;background:var(--surface);box-shadow:0 20px 60px rgba(15,23,42,.25)}.intent-card h3{margin-top:0}.intent-card dl{display:grid;grid-template-columns:120px 1fr;gap:8px;font-size:12px}.intent-card dt{color:var(--muted)}.intent-card dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.intent-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}@media(max-width:640px){.document-fields-shade{padding:10px}.document-fields-dialog{width:calc(100vw - 20px);height:calc(100dvh - 20px);max-height:calc(100dvh - 20px)}.fields-header,.fields-notice{padding:12px}.fields-footer{padding:10px 12px;justify-content:center}.fields-footer>span{width:100%;margin:0}.fields-pagination{gap:6px}.fields-pagination button{padding:7px 9px}.review-context{padding:12px}.mold-mappings{padding:12px}}
</style>
